/* LotofBench tests — workload #7, Text Processing
 * (workload_textprocessing.[ch]): corpus determinism (byte-identical
 * sources, HTML and match counts for a seed — the published
 * comparable-scores promise), input invariants (doc/pattern counts,
 * task-bytes accounting), regex engine semantics on handcrafted
 * snippets (greedy quantifiers, classes, negation, shorthands,
 * anchors, alternation, bounded repetition, error rejection),
 * Markdown conversion unit checks through the tp_markdown hook,
 * thread clamping, and goldens generated by tools/gen_goldens.c. */

#include "tests.h"

#include "lotofbench.h"
#include "sha1.h"
#include "workload_textprocessing.h"

#include <stdlib.h>
#include <string.h>

static tp_ctx *build(unsigned seed)
{
    tp_ctx *c = tp_prepare(seed);

    if (!c)
        test_fail(__FILE__, __LINE__, "tp_prepare(%u) failed", seed);
    return c;
}

/* --- determinism ------------------------------------------------------------------*/

void test_tp_corpus_deterministic(void)
{
    tp_ctx *a = build(1);
    tp_ctx *b = build(1);
    tp_ctx *c = build(2);

    if (!a || !b || !c) {
        tp_free(a);
        tp_free(b);
        tp_free(c);
        return;
    }
    CHECK_U64(tp_docs(a), TP_DOCS);
    CHECK_U64(tp_docs(b), TP_DOCS);
    for (unsigned d = 0; d < TP_DOCS; d++) {
        if (tp_doc_len(a, d) != tp_doc_len(b, d) ||
            tp_doc_html_len(a, d) != tp_doc_html_len(b, d)) {
            test_fail(__FILE__, __LINE__, "doc %u sizes differ", d);
            break;
        }
        if (memcmp(tp_doc_source(a, d), tp_doc_source(b, d),
                   tp_doc_len(a, d)) != 0 ||
            memcmp(tp_doc_html(a, d), tp_doc_html(b, d),
                   tp_doc_html_len(a, d)) != 0) {
            test_fail(__FILE__, __LINE__, "doc %u bytes differ", d);
            break;
        }
        for (unsigned k = 0; k < TP_PATTERNS; k++)
            if (tp_doc_matches(a, d, k) != tp_doc_matches(b, d, k) ||
                strcmp(tp_doc_pattern(a, d, k),
                       tp_doc_pattern(b, d, k)) != 0) {
                test_fail(__FILE__, __LINE__,
                          "doc %u pattern %u differs", d, k);
                break;
            }
    }
    /* a different seed must change at least the first document */
    CHECK(memcmp(tp_doc_source(a, 0), tp_doc_source(c, 0),
                 tp_doc_len(a, 0)) != 0);
    tp_free(a);
    tp_free(b);
    tp_free(c);
}

/* --- input invariants -------------------------------------------------------------*/

void test_tp_input_invariants(void)
{
    tp_ctx *c = build(1);
    uint64_t sum = 0;

    if (!c)
        return;
    for (unsigned d = 0; d < TP_DOCS; d++) {
        uint64_t dl = tp_doc_len(c, d);
        uint64_t hl = tp_doc_html_len(c, d);

        CHECK(dl > 1000); /* every document is a real document */
        CHECK(hl > dl);   /* conversion always adds tags */
        CHECK(tp_doc_digest(c, d) != 0);
        CHECK(tp_doc_source(c, d) != NULL);
        CHECK(tp_doc_html(c, d) != NULL);
        for (unsigned k = 0; k < TP_PATTERNS; k++) {
            CHECK(tp_doc_pattern(c, d, k) != NULL);
            CHECK(strlen(tp_doc_pattern(c, d, k)) > 0);
            CHECK(tp_doc_matches(c, d, k) <= dl);
        }
        /* task accounting: each document once for the Markdown stage
         * and once per pattern for the regex stage */
        sum += dl * (1u + TP_PATTERNS);
    }
    CHECK_U64(tp_bytes(c), sum);
    tp_free(c);
}

/* --- regex engine semantics (handcrafted snippets) ---------------------------------*/

static long q(tp_ctx *c, const char *pat, const char *txt)
{
    return tp_regex_count(c, pat, txt, strlen(txt));
}

void test_tp_regex_semantics(void)
{
    tp_ctx *c = build(1);

    if (!c)
        return;

    /* greedy quantifiers */
    CHECK(q(c, "a+", "aaa") == 1);     /* one non-overlapping match */
    CHECK(q(c, "<.+>", "<a><b>") == 1); /* greediness eats across */
    CHECK(q(c, "ab?", "a ab") == 2);
    CHECK(q(c, "a{2,3}", "aaaa") == 1); /* 3 + leftover 1: no rematch */
    CHECK(q(c, "a{2,}", "aaaa") == 1);
    CHECK(q(c, "a{2,}", "a") == 0);
    CHECK(q(c, "a{0,1}b", "ab") == 1);
    CHECK(q(c, "a*", "aaa") == 2);      /* aaa, then empty end anchor */
    CHECK(q(c, "a*", "b") == 2);        /* empty at 0 and at 1 */

    /* classes, shorthands, negation */
    CHECK(q(c, "[0-9]+", "a12b3") == 2);
    CHECK(q(c, "\\d+", "v12.34") == 2);
    CHECK(q(c, "\\w+", "ab_9") == 1);
    CHECK(q(c, "[^x]", "\n") == 1);     /* negated classes match \n */
    CHECK(q(c, "a.b", "a\nb") == 0);    /* . does not match \n */
    CHECK(q(c, "[a-z]+", "AB") == 0);
    CHECK(q(c, "\\D+", "ab1c") == 2);
    CHECK(q(c, "\\W+", "a b!c") == 2);
    CHECK(q(c, "\\S+", "a bc") == 2);
    CHECK(q(c, "[\\d]+", "x77y") == 1); /* shorthand inside a class */
    CHECK(q(c, "[]]", "a]b") == 1);     /* leading ] is literal */

    /* anchors */
    CHECK(q(c, "^a", "bab") == 0);
    CHECK(q(c, "a$", "baba") == 1);
    CHECK(q(c, "^$", "") == 1);
    CHECK(q(c, "^$", "\n") == 0);

    /* alternation and groups: leftmost-first, first branch wins */
    CHECK(q(c, "a|ab", "ab") == 1);
    CHECK(q(c, "(ab|a)", "ab") == 1);
    CHECK(q(c, "(error|warning|note): [a-z]+",
            "error: low note: hi") == 2);

    /* escapes */
    CHECK(q(c, "v\\.[0-9]+", "v.9") == 1);
    CHECK(q(c, "\\*\\*[^*]+\\*\\*", "x **bold** y") == 1);
    CHECK(q(c, "\\\\", "a\\b") == 1);

    /* malformed patterns are rejected, never silently accepted */
    CHECK(q(c, "[", "x") == -1);
    CHECK(q(c, "(", "x") == -1);
    CHECK(q(c, "a**", "x") == -1);
    CHECK(q(c, "*a", "x") == -1);
    CHECK(q(c, "a{9}", "x") == -1);
    CHECK(q(c, "\\q", "x") == -1);
    CHECK(q(c, "a{2,1}", "x") == -1);
    tp_free(c);
}

/* --- markdown conversion (handcrafted snippets) ------------------------------------*/

static long md(tp_ctx *c, const char *m, uint8_t *out, size_t cap)
{
    return tp_markdown(c, m, strlen(m), out, cap);
}

void test_tp_markdown_units(void)
{
    tp_ctx *c = build(1);
    uint8_t out[8192];
    long n;

    if (!c)
        return;

    n = md(c, "# Title Here", out, sizeof out);
    CHECK(n > 0);
    CHECK(memcmp(out, "<h1>Title Here</h1>\n", (size_t)n) == 0);

    n = md(c, "## Section", out, sizeof out);
    CHECK(n > 0 && memcmp(out, "<h2>Section</h2>\n", (size_t)n) == 0);

    n = md(c, "para one\npara two", out, sizeof out);
    CHECK(n > 0 &&
          memcmp(out, "<p>para one para two</p>\n", (size_t)n) == 0);

    n = md(c, "para A\n\npara B", out, sizeof out);
    CHECK(n > 0 && memcmp(out, "<p>para A</p>\n<p>para B</p>\n",
                          (size_t)n) == 0);

    n = md(c, "bold **x** end", out, sizeof out);
    CHECK(n > 0 &&
          strstr((const char *)out, "<strong>x</strong>") != NULL);

    n = md(c, "code `y` end", out, sizeof out);
    CHECK(n > 0 && strstr((const char *)out, "<code>y</code>") != NULL);

    n = md(c, "* one\n* two", out, sizeof out);
    CHECK(n > 0 &&
          memcmp(out, "<ul><li>one</li><li>two</li></ul>\n",
                 (size_t)n) == 0);

    n = md(c, "1. first\n2. second", out, sizeof out);
    CHECK(n > 0 &&
          memcmp(out, "<ol><li>first</li><li>second</li></ol>\n",
                 (size_t)n) == 0);

    n = md(c, "see <tag> & stuff", out, sizeof out);
    CHECK(n > 0 &&
          strstr((const char *)out, "&lt;tag&gt; &amp;") != NULL);

    n = md(c, "go [link](http://x.y) now", out, sizeof out);
    CHECK(n > 0 &&
          strstr((const char *)out,
                 "<a href=\"http://x.y\">link</a>") != NULL);

    n = md(c, "> quoted text", out, sizeof out);
    CHECK(n > 0 &&
          memcmp(out, "<blockquote>quoted text</blockquote>\n",
                 (size_t)n) == 0);

    /* generated documents: conversion never leaks a raw markup '#'
     * heading and always starts with the <h1> of the title */
    for (unsigned d = 0; d < TP_DOCS; d++) {
        const char *h = tp_doc_html(c, d);

        CHECK(h != NULL && tp_doc_html_len(c, d) > 4);
        CHECK(memcmp(h, "<h1>", 4) == 0);
    }

    /* capacity guard */
    CHECK(md(c, "a longer string", out, 4) == -1);
    CHECK(tp_markdown(c, NULL, 0, out, sizeof out) == -1);
    tp_free(c);
}

/* --- threading ----------------------------------------------------------------------*/

void test_tp_thread_clamp(void)
{
    tp_ctx *c = build(1);
    unsigned t;
    double mbps;
    uint64_t bytes;

    if (!c)
        return;
    t = 1000;
    CHECK(tp_run(c, 1, &t, &mbps, &bytes) == 0);
    CHECK(t == TP_DOCS); /* clamped: one document per thread at least */
    t = 0;
    CHECK(tp_run(c, 1, &t, &mbps, &bytes) == 0);
    CHECK(t == 1);
    tp_free(c);
}

/* --- sane runs -----------------------------------------------------------------------*/

void test_tp_run_sane(void)
{
    tp_ctx *c = build(1);
    unsigned t;
    double mbps;
    uint64_t bytes;

    if (!c)
        return;
    t = 1;
    mbps = 0.0;
    CHECK(tp_run(c, 1, &t, &mbps, &bytes) == 0);
    CHECK(mbps > 1.0 && mbps < 100000.0);
    CHECK_U64(bytes, tp_bytes(c));
    t = 2;
    CHECK(tp_run(c, 1, &t, &mbps, &bytes) == 0);
    tp_free(c);
}

/* --- null and range safety ------------------------------------------------------------*/

void test_tp_accessors_null_safe(void)
{
    tp_ctx *c = build(1);

    CHECK(tp_docs(NULL) == 0);
    CHECK_U64(tp_bytes(NULL), 0);
    CHECK_U64(tp_doc_len(NULL, 0), 0);
    CHECK(tp_doc_source(NULL, 0) == NULL);
    CHECK(tp_doc_pattern(NULL, 0, 0) == NULL);
    CHECK_U64(tp_doc_matches(NULL, 0, 0), 0);
    CHECK_U64(tp_doc_html_len(NULL, 0), 0);
    CHECK(tp_doc_html(NULL, 0) == NULL);
    CHECK_U64(tp_doc_digest(NULL, 0), 0);
    CHECK(tp_regex_count(NULL, "a", "a", 1) == -1);
    CHECK(tp_markdown(NULL, "a", 1, NULL, 0) == -1);
    if (c) {
        CHECK_U64(tp_doc_len(c, TP_DOCS), 0);
        CHECK(tp_doc_source(c, TP_DOCS) == NULL);
        CHECK(tp_doc_pattern(c, 0, TP_PATTERNS) == NULL);
        CHECK_U64(tp_doc_matches(c, 0, TP_PATTERNS), 0);
        tp_free(c);
    }
}

/* --- goldens --------------------------------------------------------------------------*/

void test_tp_golden(void)
{
    tp_ctx *c = build(1);
    char hex[41];

    if (!c)
        return;
    /* document 0 (API-doc archetype), generated by tools/gen_goldens.c */
    sha1_hex((const uint8_t *)tp_doc_source(c, 0), tp_doc_len(c, 0), hex);
    CHECK_STR(hex, "e87ab337e9fe7a0ed8d7a30210317c606837533f");
    CHECK_U64(tp_doc_len(c, 0), 35654);
    sha1_hex((const uint8_t *)tp_doc_html(c, 0), tp_doc_html_len(c, 0),
             hex);
    CHECK_STR(hex, "a6e3d8a91a5bf8527e453d33fb718bc978cd1a3b");
    CHECK_U64(tp_doc_html_len(c, 0), 46261);
    CHECK_STR(tp_doc_pattern(c, 0, 0), "`[^`]+`");
    CHECK_U64(tp_doc_matches(c, 0, 0), 503);
    CHECK_U64(tp_bytes(c), 13317768);
    tp_free(c);
}
